CREATE TYPE "UploadStatus" AS ENUM ('INITIATED','UPLOADING','VERIFYING','SCANNING','AVAILABLE','FAILED','ABORTED','EXPIRED','QUARANTINED');
CREATE TABLE "UploadSession" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"actorId" UUID NOT NULL,"originalFilename" TEXT NOT NULL,"declaredSize" BIGINT NOT NULL,"mimeType" TEXT NOT NULL,"storageProvider" TEXT NOT NULL DEFAULT 'LOCAL',"storageKey" TEXT NOT NULL,"providerUploadId" TEXT,"status" "UploadStatus" NOT NULL DEFAULT 'INITIATED',"partSize" INTEGER NOT NULL,"totalParts" INTEGER NOT NULL,"uploadedBytes" BIGINT NOT NULL DEFAULT 0,"checksum" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"abortedAt" TIMESTAMP(3),CONSTRAINT "UploadSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UploadPart" ("id" UUID NOT NULL,"uploadSessionId" UUID NOT NULL,"partNumber" INTEGER NOT NULL,"size" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"storagePath" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "UploadPart_pkey" PRIMARY KEY ("id"));
CREATE INDEX "UploadSession_organizationId_actorId_status_idx" ON "UploadSession"("organizationId","actorId","status");
CREATE INDEX "UploadSession_expiresAt_status_idx" ON "UploadSession"("expiresAt","status");
CREATE UNIQUE INDEX "UploadPart_uploadSessionId_partNumber_key" ON "UploadPart"("uploadSessionId","partNumber");
ALTER TABLE "UploadPart" ADD CONSTRAINT "UploadPart_uploadSessionId_fkey" FOREIGN KEY ("uploadSessionId") REFERENCES "UploadSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
